using Rotaidem.Licensing;
using Xunit;

namespace Rotaidem.Licensing.Tests;

public class LicenseKeyTests
{
    // Keys generated by the website (server.py). The C# check must agree with the server's.
    [Theory]
    [InlineData("HPRO-YWX8-C8H5-8F94")]
    [InlineData("HPRO-3WQY-NNDZ-3L3U")]
    [InlineData("HPRO-P2PW-QHPF-UT7S")]
    [InlineData("HPRO-58E5-3PAF-L3A9")]
    public void Accepts_keys_made_by_the_server(string key) => Assert.True(LicenseKey.IsWellFormed(key, "HPRO"));

    [Fact]
    public void Generated_keys_have_the_right_shape_and_validate()
    {
        for (var i = 0; i < 1000; i++)
        {
            var key = LicenseKey.Generate();
            Assert.Matches("^HPRO-[A-Z2-9]{4}-[A-Z2-9]{4}-[A-Z2-9]{4}$", key);
            Assert.DoesNotContain('I', key[5..]);
            Assert.DoesNotContain('O', key[5..]);
            Assert.True(LicenseKey.IsWellFormed(key));
        }
    }

    [Fact]
    public void Every_single_character_typo_is_caught()
    {
        var key = LicenseKey.Generate();
        var chars = key.Replace("-", "")[4..];
        for (var pos = 0; pos < 12; pos++)
        {
            foreach (var c in LicenseKey.Alphabet.Where(c => c != chars[pos]))
            {
                var typo = chars[..pos] + c + chars[(pos + 1)..];
                Assert.False(LicenseKey.IsWellFormed($"HPRO-{typo[..4]}-{typo[4..8]}-{typo[8..]}"));
            }
        }
    }

    [Theory]
    [InlineData(" hpro-yWx8-c8h5-8f94 ", "HPRO-YWX8-C8H5-8F94")]
    [InlineData("HPRO-YWX8 -C8H5-8F94", "HPRO-YWX8-C8H5-8F94")]
    public void Normalizes_case_and_spaces(string input, string expected) => Assert.Equal(expected, LicenseKey.Normalize(input));

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("HPRO-AAAA-AAAA-AAAA")]
    [InlineData("HPRO-YWX8-C8H5-8F9")]
    [InlineData("HPRO-YWX8-C8H5-8F940")]
    [InlineData("HPRO-YWX8-C8H5-8F9O")]
    public void Rejects_bad_keys(string? input) => Assert.Null(LicenseKey.Normalize(input));

    [Fact]
    public void Prefix_is_part_of_the_check() => Assert.False(LicenseKey.IsWellFormed("ABCD-YWX8-C8H5-8F94"));

    [Fact]
    public void Store_round_trips()
    {
        var dir = Path.Combine(Path.GetTempPath(), "rotaidem-test-" + Guid.NewGuid());
        var store = new LicenseStore("heavypro", dir);
        Assert.Null(store.Load());
        store.Save(" hpro-ywx8-c8h5-8f94", DateTimeOffset.UnixEpoch);
        Assert.Equal("HPRO-YWX8-C8H5-8F94", store.Load()?.Key);
        store.Clear();
        Assert.Null(store.Load());
        Directory.Delete(dir, true);
    }

    [Fact]
    public void Reads_files_written_by_the_earlier_version()
    {
        var dir = Path.Combine(Path.GetTempPath(), "rotaidem-test-" + Guid.NewGuid());
        Directory.CreateDirectory(dir);
        File.WriteAllText(Path.Combine(dir, "license.json"), "{\"Key\":\"HPRO-YWX8-C8H5-8F94\",\"LastValidatedUtc\":\"2026-10-19T19:00:00+00:00\"}");
        var saved = new LicenseStore("heavypro", dir).Load();
        Assert.Equal("HPRO-YWX8-C8H5-8F94", saved?.Key);
        Assert.Equal(new DateTimeOffset(2026, 10, 19, 19, 0, 0, TimeSpan.Zero), saved?.LastValidatedUtc);
        Directory.Delete(dir, true);
    }

    [Fact]
    public void Machine_id_is_stable_and_anonymous()
    {
        var id = MachineId.Get();
        Assert.Equal(id, MachineId.Get());
        Assert.Matches("^[0-9a-f]{32}$", id);
    }
}
